"""Small standard-library KDL reader for Dasel's common document subset."""
import re

_TOKEN = re.compile(r'\s*(?:(//[^\n]*)|("(?:\\.|[^"\\])*"|\'(?:\\.|[^\'\\])*\')|([{};=])|([^\s{};=]+))')


def _scalar(s):
    if s.startswith('"') or s.startswith("'"):
        if s.startswith('"'):
            try:
                import json
                return json.loads(s)
            except Exception:
                pass
        return s[1:-1]
    if s in ('#true', '#false', '#null'):
        return {'#true': True, '#false': False, '#null': None}[s]
    if s.startswith('#'):
        return s[1:]
    try:
        if re.fullmatch(r'[+-]?\d+', s):
            return int(s)
        if re.fullmatch(r'[+-]?(?:\d+\.\d*|\.\d+|\d+[eE][+-]?\d+|\d+\.\d*[eE][+-]?\d+)', s):
            return float(s)
    except ValueError:
        pass
    return s


