import csv
import io
import xml.etree.ElementTree as ET


def parse_csv(text, delimiter=','):
    reader = csv.DictReader(io.StringIO(text), delimiter=delimiter)
    return [{str(k): (v if v is not None else '') for k, v in row.items() if k is not None}
            for row in reader]


def _element(el):
    obj = {'-' + k: v for k, v in el.attrib.items()}
    for child in el:
        value = _element(child)
        key = child.tag
        if key in obj:
            old = obj[key]
            if not isinstance(old, list): old = [old]
            old.append(value)
            obj[key] = old
        else:
            obj[key] = value
    text = (el.text or '').strip()
    if not obj:
        return text
    if text:
        obj['#text'] = text
    return obj


def parse_xml(text):
    root = ET.fromstring(text)
    return {root.tag: _element(root)}
