def dump_xml(value):
    if not isinstance(value, dict) or len(value)!=1:
        raise ValueError('xml writer expects root output to be a map with one key')
    tag, contents=next(iter(value.items()))
    def emit(name, val, depth):
        indent=' '*depth
        if isinstance(val,list): return '\n'.join(emit(name,x,depth) for x in val)
